def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    pts = {1, n + 1}
    for op in ops:
        pts.add(op[1])
        pts.add(op[2] + 1)
    xs = sorted(pts)
    pos = {x: i for i, x in enumerate(xs)}
    m = len(xs) - 1

    size = 4 * m
    ttype = [0] * size  # 0 = chmax with tval, 1 = assign tval
    tval = [0] * size

    def apply(node, t, v):
        if t == 1:
            ttype[node] = 1
            tval[node] = v
        elif v > tval[node]:
            tval[node] = v

    def push(node):
        if ttype[node] or tval[node]:
            apply(2 * node, ttype[node], tval[node])
            apply(2 * node + 1, ttype[node], tval[node])
            ttype[node] = 0
            tval[node] = 0

    def update(node, lo, hi, L, R, t, v):
        if R < lo or hi < L:
            return
        if L <= lo and hi <= R:
            apply(node, t, v)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, L, R, t, v)
        update(2 * node + 1, mid + 1, hi, L, R, t, v)

    counts = {}

    def collect(node, lo, hi):
        if lo == hi:
            v = tval[node]
            if v:
                counts[v] = counts.get(v, 0) + xs[lo + 1] - xs[lo]
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid + 1, hi)

    for op in ops:
        L = pos[op[1]]
        R = pos[op[2] + 1] - 1
        if op[0] == 1:
            update(1, 0, m - 1, L, R, 0, op[3])
        else:
            update(1, 0, m - 1, L, R, 1, 0)

    collect(1, 0, m - 1)
    return [[c, counts[c]] for c in sorted(counts)]
